10	
11	#include "kernel_operator.h"
12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelHardswish {
17	public:
18	    __aicore__ inline KernelHardswish() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	
26	        if (blockIdx < formerNum) {
27	            this->blockLength = formerLength;
28	            int64_t offset = formerLength * blockIdx;
29	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
30	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
31	        } else {
32	            this->blockLength = tailLength;
33	            int64_t tailIdx = blockIdx - formerNum;
34	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
35	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
36	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
37	        }
38	
39	        this->tileLength = tileLength;
40	
41	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
42	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
43	
44	        if constexpr (sizeof(T) == sizeof(float)) {
45	            pipe.InitBuffer(calcBuf, tileLength * sizeof(float));
46	        } else {
47	            pipe.InitBuffer(calcBuf1, tileLength * sizeof(float));
48	            pipe.InitBuffer(calcBuf2, tileLength * sizeof(float));
49	        }
50	    }
51	
52	    __aicore__ inline void Process()
53	    {
54	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
55	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
56	
57	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
58	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
59	
60	        for (int64_t i = 0; i < tileNum - 1; ++i) {
61	            CopyIn(i, this->tileLength);
62	            Compute(i, this->tileLength);
63	            CopyOut(i, this->tileLength);
64	        }
65	        if (tileNum > 0) {
66	            CopyIn(tileNum - 1, alignedTailLen);
67	            Compute(tileNum - 1, alignedTailLen);
68	            CopyOut(tileNum - 1, alignedTailLen);
69	        }
70	    }
71	
72	private:
73	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
74	    {
75	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
76	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
77	        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
78	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
79	        inQueueX.EnQue(xLocal);
80	    }
81	
82	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
83	    {
84	        if constexpr (sizeof(T) == sizeof(float)) {
85	            ComputeFloat32(progress, curTileLength);
86	        } else {
87	            ComputeFloat16Bf16(progress, curTileLength);
88	        }
89	    }
90	
91	    __aicore__ inline void ComputeFloat32(int64_t progress, int64_t curTileLength)
92	    {
93	        AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
94	        AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
95	        AscendC::LocalTensor<float> tmp1 = calcBuf.Get<float>();
96	
97	        // tmp1 = copy of x (preserved for final multiply)
98	        AscendC::DataCopy(tmp1, xLocal, curTileLength);
99	
100	        // Compute hardswish in-place on yLocal:
101	        // hardswish(x) = x * min(max(x+3, 0), 6) / 6
102	        AscendC::Adds(yLocal, xLocal, 3.0f, curTileLength);           // y = x + 3
103	        AscendC::Relu(yLocal, yLocal, curTileLength);                  // y = max(x+3, 0)
104	        AscendC::Mins(yLocal, yLocal, 6.0f, curTileLength);           // y = min(max(x+3,0), 6)
105	        AscendC::Muls(yLocal, yLocal, 1.0f / 6.0f, curTileLength);   // y = relu6(x+3) / 6
106	        AscendC::Mul(yLocal, tmp1, yLocal, curTileLength);            // y = x * (relu6/6)
107	
108	        outQueueY.EnQue<float>(yLocal);
109	        inQueueX.FreeTensor(xLocal);
110	    }
111	
112	    __aicore__ inline void ComputeFloat16Bf16(int64_t progress, int64_t curTileLength)
113	    {
114	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
115	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
116	        AscendC::LocalTensor<float> xFp32 = calcBuf1.Get<float>();
117	        AscendC::LocalTensor<float> tmpFp32 = calcBuf2.Get<float>();
118	
119	        // Cast input to fp32 (xFp32 preserved for final multiply)
120	        AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
121	
122	        // Compute hardswish: x * relu6(x+3) / 6
123	        // Use tmpFp32 for intermediate computation
124	        AscendC::Adds(tmpFp32, xFp32, 3.0f, curTileLength);           // tmp = x + 3
125	        AscendC::Relu(tmpFp32, tmpFp32, curTileLength);                // tmp = max(x+3, 0)
126	        AscendC::Mins(tmpFp32, tmpFp32, 6.0f, curTileLength);         // tmp = min(max(x+3,0), 6)
127	        AscendC::Muls(tmpFp32, tmpFp32, 1.0f / 6.0f, curTileLength); // tmp = relu6(x+3) / 6
128	        AscendC::Mul(tmpFp32, xFp32, tmpFp32, curTileLength);         // tmp = x * (relu6/6)
129	
130	        // Cast back to half/bf16
131	        AscendC::Cast(yLocal, tmpFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
132	
133	        outQueueY.EnQue<T>(yLocal);
134	        inQueueX.FreeTensor(xLocal);
135	    }
136	
137	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
138	    {
139	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
140	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
141	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
142	        outQueueY.FreeTensor(yLocal);
143	    }
144	
145	private:
146	    AscendC::TPipe pipe;
147	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
148	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
149	    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBuf;
150	    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBuf1;
151	    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBuf2;
152	    AscendC::GlobalTensor<T> xGm;
153	    AscendC::GlobalTensor<T> yGm;
154	    int64_t blockLength;
155	    int64_t tileLength;
156	};
157	
158	extern "C" __global__ __aicore__ void hardswish(GM_ADDR x, GM_ADDR y,
159	                                                  int64_t formerNum, int64_t formerLength,
160	                                                  int64_t tailLength, int64_t tileLength,
161	                                                  int64_t dtypeSize)
162	{
163	    if (dtypeSize == 2) {
164	        KernelHardswish<half> op;
165	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
166	        op.Process();
167	    } else {
168	        KernelHardswish<float> op;
169	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
170	        op.Process();
171	    }
172	}
