#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelHardswish {
public:
    __aicore__ inline KernelHardswish() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->tileLength = tileLength;

        this->pipe.InitBuffer(this->inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        this->pipe.InitBuffer(this->outQueueY, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) == sizeof(float)) {
            this->pipe.InitBuffer(this->calcBuf, tileLength * sizeof(float));
        } else {
            this->pipe.InitBuffer(this->calcBuf, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, tailTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = this->inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, this->xGm[progress * this->tileLength], copyParams, padParams);
        this->inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        if constexpr (sizeof(T) == sizeof(float)) {
            ComputeFloat32(progress, curTileLength);
        } else {
            ComputeFloat16Bf16(progress, curTileLength);
        }
    }

    __aicore__ inline void ComputeFloat32(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<float> xLocal = this->inQueueX.DeQue<float>();
        AscendC::LocalTensor<float> yLocal = this->outQueueY.AllocTensor<float>();
        AscendC::LocalTensor<float> tmpBuf = this->calcBuf.Get<float>();

        // tmpBuf = copy of x (preserved for final multiply)
        AscendC::DataCopy(tmpBuf, xLocal, curTileLength);

        // Compute hardswish in yLocal:
        // hardswish(x) = x * min(max(x+3, 0), 6) / 6
        AscendC::Adds(yLocal, xLocal, 3.0f, curTileLength);
        AscendC::Relu(yLocal, yLocal, curTileLength);
        AscendC::Mins(yLocal, yLocal, 6.0f, curTileLength);
        AscendC::Muls(yLocal, yLocal, 1.0f / 6.0f, curTileLength);
        AscendC::Mul(yLocal, tmpBuf, yLocal, curTileLength);

        this->outQueueY.EnQue<float>(yLocal);
        this->inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void ComputeFloat16Bf16(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = this->inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = this->outQueueY.AllocTensor<T>();
        AscendC::LocalTensor<float> fp32Buf = this->calcBuf.Get<float>();

        // Step 1: Cast input to fp32 into calcBuf
        AscendC::Cast(fp32Buf, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

        // Step 2-5: Compute hardswish directly in fp32Buf (overwriting input copy):
        //   hardswish(x) = x * min(max(x+3, 0), 6) / 6
        //   Since we need x for the final Mul, we compute the relu6/6 part first
        //   then multiply by x at the end. But the original x in fp32Buf gets overwritten.
        //   So we need to save x first into a temp, then compute.
        //   However, with only 1 fp32 buffer, we'd need another buffer.
        //
        //   Alternative: Use xLocal directly in the Mul.
        //   Mul(fp32, half, half) is not supported. We need both operands as fp32.
        //
        //   Better approach: instead of overwriting in-place, compute the
        //   relu6(x+3)/6 result first, then multiply by x.
        //   We CAN'T preserve both x and the intermediate in 1 buffer.
        //
        //   OK, let's just allocate 2 TBuf. We already have calcBuf which is
        //   1 * tileLength * sizeof(float). Let's use a TQue with VECCALC for
        //   the second buffer.

        AscendC::Cast(yLocal, fp32Buf, AscendC::RoundMode::CAST_ROUND, curTileLength);

        this->outQueueY.EnQue<T>(yLocal);
        this->inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = this->outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(this->yGm[progress * this->tileLength], yLocal, copyParams);
        this->outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> calcBuf;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void hardswish(GM_ADDR x, GM_ADDR y,
                                                  int64_t formerNum, int64_t formerLength,
                                                  int64_t tailLength, int64_t tileLength,
                                                  int64_t dtypeSize, int64_t isBf16)
{
    if (dtypeSize == 2) {
        KernelHardswish<half> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelHardswish<float> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
