        AscendC::LocalTensor<float> tmpBuf = calcBuf.Get<float>();

        // tmpBuf = copy of x (preserved for final multiply)
        AscendC::DataCopy(tmpBuf, xLocal, curTileLength);

        // Compute hardswish: x * min(max(x+3, 0), 6) / 6
        AscendC::Adds(yLocal, xLocal, 3.0f, curTileLength);
        AscendC::Relu(yLocal, yLocal, curTileLength);
        AscendC::Mins(yLocal, yLocal, 6.0f, curTileLength);
