18	
19	at::Tensor hardswish(const at::Tensor &self)
20	{
21	    // ---- 输入校验 ----
22	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat ||
23	                self.scalar_type() == at::kBFloat16,
24	                "hardswish: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
25	
26	    at::Tensor output = at::empty_like(self);
27	
28	    int64_t totalLength = self.numel();
29	    if (totalLength == 0) {
30	        return output;
31	    }
32	
33	    int64_t dtypeSize = self.element_size();
34	
35	    // ---- 获取硬件参数 ----
36	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
37	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
38	    uint64_t ubSize;
39	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
40	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
41	
42	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
43	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
44	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
45	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
46	
47	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
48	    int64_t formerNum = usedCoreNum - 1;
49	    int64_t formerLength = totalLengthCoreAlign;
50	    int64_t tailLength = totalLength - formerNum * formerLength;
51	
52	    // ---- UB 级 tiling (核内切分) ----
53	    // fp32: bufferCoefficient = 20  (2 TQue * 2 buf * 4B + 1 TBuf * 4B)
54	    // fp16/bf16: bufferCoefficient = 16  (2 TQue * 2 buf * 2B + 2 TBuf * 4B)
55	    int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
56	
57	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
58	    int64_t alignElements = 32 / dtypeSize;
59	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
60	
61	    // BlockDim 必须是 uint32_t 左值
62	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
63	
64	    // 所有 EXEC_KERNEL_CMD 参数必须是左值
65	    int64_t formerNum_lv = formerNum;
66	    int64_t formerLength_lv = formerLength;
67	    int64_t tailLength_lv = tailLength;
